"""Generate P4 parameter order and hard validation bounds from the desktop schema."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render():
    fields = json.loads((ROOT / 'desktop/resources/config/control_parameters.schema.json').read_text(encoding='utf-8'))['fields']
    def symbol(field):
        return ''.join(word.title() for word in (field['group'] + '_' + field['name']).split('_'))
    def literal(value):
        return f'{float(value):.8g}' + ('.0f' if float(value).is_integer() else 'f')
    return '\n'.join([
        '// Generated by tools/generate_control_parameters.py; do not edit.',
        '/** @file ControlParameters.generated.h',
        ' * @brief 上位机参数模式生成的枚举顺序及硬校验边界。',
        ' */',
        '#pragma once', '#include <stddef.h>', 'namespace mmhand::control {',
        'enum Parameter : size_t {',
        *[f'    {symbol(field)} = {i},' for i, field in enumerate(fields)],
        f'    ParameterCount = {len(fields)}', '};',
        'inline constexpr float kParameterMinimum[] = {',
        *[f'    {literal(field["minimum"])},' for field in fields], '};',
        'inline constexpr float kParameterMaximum[] = {',
        *[f'    {literal(field["maximum"])},' for field in fields], '};',
        '} // namespace mmhand::control', '',
    ])


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    output = ROOT / 'ESP32-P4/src/generated/ControlParameters.generated.h'
    expected = render()
    if args.check:
        if not output.exists() or output.read_text(encoding='utf-8') != expected:
            raise SystemExit('Control parameter header is out of date')
    else:
        output.write_text(expected, encoding='utf-8')
